local B = bit32 or bit
if not B then
    B = {}
    function B.bxor(a, b)
        local r, m = 0, 1
        for _ = 1, 32 do
            local aa, bb = a % 2, b % 2
            if aa ~= bb then r = r + m end
            a, b = (a - aa) / 2, (b - bb) / 2
            m = m * 2
        end
        return r
    end
end

